    Term req = apply(a->cont, a->item);
    u64 tg = TAG(req);
    if (tg == 0) {
      bend_drop(req);
      io_act_free(a);
      io_live -= 1;
      return -1;
    }
    if (tg == 1) {
      io_errs(e, FLD(req, 1));
      return (int)(u32)FLD(req, 0);
    }
    if (CID_KIND(tg & 0xffffff) != 3 || io_eff_rows[CID_TAG(tg)].run == NULL) err_fail("an alien request");
    u32 need = io_eff_rows[CID_TAG(tg)].ask;
    a->cont = req;
    if (need != 0) {
      Term f0 = FLD(req, 0);
      u32 word = (u32)(need & IO_READ ? io_hand_v(f0) : f0);
      io_wait_on(&a->work, (int)word, need & IO_READ ? POLLIN : 0,
        need & IO_TIME ? io_tick() + (u64)word * 1000000ull : 0, io_exec);
      return -1;
    }
