  if (i != ~0u) {
    chan_idle = chan_rows[i].next;
  } else {
    if (chan_len == 1u << 24) err_fail("more than 16777216 channels at once");
    if ((chan_len & (chan_len - 1)) == 0)
      chan_rows = io_mem(realloc(chan_rows, (chan_len == 0 ? 1 : 2 * chan_len) * sizeof(ChanRow)));
    i = chan_len;
    chan_len += 1;
    chan_rows[i].gen = 0;
  }
  ChanRow *row = &chan_rows[i];
  row->gen += 1;
  row->room = room;
  row->size = 0;
  row->head = 0;
  row->shut = 0;
  row->ring = room == 0 ? NULL : io_mem(calloc(room, sizeof(Term)));
  row->wait.head = NULL;
  row->wait.last = NULL;
